function AppointLeader(name)

	PushDebugMessage('Change Lear: '..name)

	local count = DataPool:GetTeamMemberCount();

	local szNick;
	local iFamily;
	local iLevel;
	local bDeadlink;
	local bDead;
	local bSex;
    local sZoneWorldID

	for i = 0, count - 1 do
		szNick
		,iFamily
		,iLevel
		,bDead
		,bDeadlink
		,bSex
		,sZoneWorldID
		= DataPool:GetTeamMemInfoByIndex(i);
		if szNick == name then
			Player:AppointLeader(i);
			break;
		end
	end

end

function XuatPet(id)
	for i = 1, 10 do 
		strName,strName2,sex = Pet:GetID(i-1);
		if strName2 == id then 
			Pet:Feed(i-1);
			Pet:Dome(i-1);
			Pet:Go_Fight(i-1);
			return;
		end 
	end
end

function MissionInfo(n)	
	if n == nil then
		return '0'
	end
	cnt = 0;
	n = string.lower(n);	
	string.gsub(n, "%s+", "")
	while true do 
		local name, content = DataPool:GetPlayerMission_Memo(cnt); 
		name = string.lower(name);
		string.gsub(name, "%s+", "")
		if string.find(name, n) then
			if DataPool:GetPlayerMission_Variable(cnt, 0) == 1 then 
				return '1';
			else
				return content;
			end
		end 
		cnt = cnt + 1; 
		if cnt == 20 then 
			return '0';
		end 
	end
end

function Quest_Open()
	this:Show();

	NpcName = Target:GetDialogNpcName();
	MapID = GetSceneID();

	if string.find(NpcName, 'Mô Kim Hiệu Úy') then 
		QuestFrameOptionClicked(-1, 50063, 100); 
	end

	if string.find(NpcName, 'Ác Tặc Tạo Phản') then
	   if MapID == 3 then
			QuestFrameOptionClicked(-1, 50013, -1);
		elseif MapID == 4 then
			QuestFrameOptionClicked(-1, 50013, -1);
		elseif MapID == 5 then
			QuestFrameOptionClicked(-1, 50013, -1);
		elseif MapID == 6 then
			QuestFrameOptionClicked(-1, 50013, -1);
		elseif MapID == 7 then
			QuestFrameOptionClicked(-1, 50013, -1);
		elseif MapID == 8 then
			QuestFrameOptionClicked(-1, 50013, -1);
		end
	end

	if string.find(NpcName, 'Thiếu Lâm Vân Du Võ Tăng') then
	   if MapID == 18 then
			QuestFrameOptionClicked(-1, 808042, 1);
		elseif MapID == 24 then
			QuestFrameOptionClicked(-1, 808042, 1);
		elseif MapID == 30 then
			QuestFrameOptionClicked(-1, 808042, 1);
		elseif MapID == 272 then
			QuestFrameOptionClicked(-1, 402108, 1);
		end
	end

	if string.find(NpcName, 'Giang Hồ Tiêu Tiểu') or string.find(NpcName, 'Giang hồ tiêu tiểu') or string.find(NpcName, 'Giang hồ tà đạo') then
		if MapID == 9then
			QuestFrameOptionClicked(-1, 808027, 0);
		elseif MapID == 10 then
			QuestFrameOptionClicked(-1, 808032, 0);
		elseif MapID == 11 then
			QuestFrameOptionClicked(-1, 808031, 0);
		elseif MapID == 12 then
			QuestFrameOptionClicked(-1, 808033, 0);
		elseif MapID == 13 then
			QuestFrameOptionClicked(-1, 808029, 0);
		elseif MapID == 14 then
			QuestFrameOptionClicked(-1, 808016, 0);
		elseif MapID == 15 then
			QuestFrameOptionClicked(-1, 808034, 0);
		elseif MapID == 16 then
			QuestFrameOptionClicked(-1, 808028, 0);
		elseif MapID == 17 then
			QuestFrameOptionClicked(-1, 808030, 0);
		elseif MapID == 284 then
			QuestFrameOptionClicked(-1, 808043, 0);
		end
	end

	if (string.find(NpcName, 'Đinh Đinh') or string.find(NpcName, 'Đông Đông')) and MapID == 0 then
		QuestFrameOptionClicked(-1, 800116, 2);
	end

	if string.find(NpcName, 'Mạnh Bà') then
		if MapID == 77 then
			QuestFrameOptionClicked(-1, 77001, 0)
		end
		if MapID == 578 then
			QuestFrameOptionClicked(-1, 77001, 0)
		end
	end



	if string.find(NpcName, 'Long Bá Thiên') then
		if MapID == 0 or MapID == 242 then
			QuestFrameOptionClicked(-1,129,0);
			QuestFrameOptionClicked(-1,129,1001);			
		end
	end
end
