function ChatFrame_TextAccepted()
	if G_TheCurrentChannel == nil then
		G_TheCurrentChannel = 'near'
	end
	local txt = MainMenuBar_EditBox:GetItemElementsString();
	TXT = txt

	MapID = GetSceneID();
	if txt == '@map' then
		PushDebugMessage('Map hiện tại: '..MapID)
	end

	local bChatAction = 0;
	if (bChatAction == 1) then		
		g_ChatActionTxt = txt
		ChatFrame_SetEditBoxTxt("")
		Talk : CanDoDoubleAction_Bar()
	elseif (bChatAction == 2) then
		g_ChatActionTxt = ""
		ChatFrame_SetEditBoxTxt("")
	elseif (bChatAction == 0) then		
		local prvname,perColor = Talk : SendChatMessage(G_TheCurrentChannel, txt);
		if(nil == prvname ) then prvname = ""; end
		if(nil == perColor ) then perColor = ""; end
		local str = "";
		if(prvname == "")then
			str = str..perColor;
		else
			str = str.."/"..prvname.." "..perColor;
		end		
		if("" ~= str) then
			ChatFrame_SetEditBoxTxt(str);
		else
			ChatFrame_SetEditBoxTxt("");
		end
	end	
end
function  MessageBox_Self_UpdateRect()
	local nWidth, nHeight = MessageBox_Self_Text:GetWindowSize();
	local nTitleHeight = 36;
	local nBottomHeight = 75;
	nWindowHeight = nTitleHeight + nBottomHeight + nHeight;
	MessageBox_Self_Frame:SetProperty( "AbsoluteHeight", tostring( nWindowHeight ) );
	if tonumber(arg0) == 24 or arg0 == '#{SJXL_120423_08}' then		
		IsMessageBox = true;	
	else
		IsMessageBox = false;
	end
end
function AcceptBox_ResetFrame()
	AcceptBox_PageHeader_Name:SetText("")
	AcceptBox_OK_Button:Enable()
	AcceptBox_OK_Button:Show()
	AcceptBox_OK_Button:SetText("#{INTERFACE_XML_557}")
	AcceptBox_Cancel_Button:Enable()
	AcceptBox_Cancel_Button:Show()
	AcceptBox_Cancel_Button:SetText("#{INTERFACE_XML_542}")
	AcceptBox_Frame:SetProperty("AbsoluteSize", FrameSize_Original)
	AcceptBox_Blank:SetProperty("UnifiedSize", AcceptBox_Blank_Orignial_Size)
	if tonumber(arg0) == 20100717 then
		IsAcceptBox = true;
	else
		IsAcceptBox = false;
	end
end
function MessageBox_Other_UpdateFrame()	
	local nWidth, nHeight = MessageBox_Other_Text:GetWindowSize();
	local nTitleHeight = 36;
	local nBottomHeight = 75;
	nWindowHeight = nTitleHeight + nBottomHeight + nHeight;
	MessageBox_Other_Frame:SetProperty( "AbsoluteHeight", tostring( nWindowHeight ) );
	local txt = MessageBox_Other_Text:GetText();
	if string.find(txt, 'Bạn có muốn vào nhóm không?') then
		setmetatable(_G, {__index = MessageBox_Other_Env});
		[REDACTED]();
		--IsMessageBoxOther = true;
	--else
		--IsMessageBoxOther = false;
	end
end

