function HuyNhiemVu(nhiemvu)
	if nhiemvu == nil then
		return
	end
	while true do 
		local name, content = DataPool:GetPlayerMission_Memo(cnt); 
		if string.find(name, nhiemvu) then 
			if DataPool:GetPlayerMission_Variable(cnt, 0) ~= 1 then 
				DataPool:Mission_Abnegate_Popup(cnt,DataPool:GetPlayerMission_Memo(cnt));
				setmetatable(_G, {__index = MessageBox_Self_Env}); 
				MessageBox_Self_OK_Clicked();
			end 
		end 
		cnt = cnt + 1; 
		if cnt == 20 then 
			return
		end 
	end
end
function ReadMissionOutline()
	MISSION = "";
	for i=1,200 do
		local iMissionType = i;
		local DeployNum = GetMissionOutlineNum(iMissionType);
		local nMyLevel = Player:GetData("LEVEL");
		 for i=1, DeployNum do
			local MissionLevel, MinLevel, MaxLevel, strNpcName, strNpcPos, strScene, strMissionName, PosX, PosY, SceneID = GetMissionOutlineInfo(iMissionType, i);		
			if(MissionLevel <= nMyLevel) then
				local strInfo = "";
				strNpcPos = "#{_INFOAIM"..(PosX)..","..(PosY)..","..(SceneID)..","..(strNpcName).."}";
				if strScene and strScene ~= "" then
					strInfo = strInfo.."   #G"..strScene.."  #R"..strNpcName..strNpcPos;
				else
					strInfo = strInfo.."   #R"..strNpcName..strNpcPos
				end
				MISSION = MISSION .. strMissionName .. '=' .. strInfo .. ';';
			end
		end
	end
	return MISSION;
end
